public sealed class ApplicationIdentity {
 public bool FingerprintCached,SignatureChecked;
 public string Name{get;set;}public string Publisher{get;set;}public string Product{get;set;}public string Version{get;set;}public string Company{get;set;}public string Executable{get;set;}public string InstallDirectory{get;set;}public string Signature{get;set;}public string Signer{get;set;}public string Evidence{get;set;}
 public string PortableRoot{get;set;}
 public string SearchText{get{return String.Join(" ",new[]{Name,Publisher,Product,Company,Executable});}}
}
public sealed class CacheSearchReport {public int Directories,Caches,Unreadable;public bool Limited;}
public sealed class DiscoveryResult {public CacheSearchReport CacheSearch;public List<ApplicationIdentity> Applications=new List<ApplicationIdentity>();public int Unreadable;public string Summary{get{return "发现 "+Applications.Count+" 个应用指纹"+(Unreadable>0?" · "+Unreadable+" 处无法读取":"");}}}
public static class ApplicationDiscovery {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct TrustFile {public uint Size;[MarshalAs(UnmanagedType.LPWStr)]public string Path;public IntPtr Handle,Subject;}
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]struct TrustData {public uint Size;public IntPtr Policy,Sip;public uint UI,Revocation,Choice;public IntPtr File;public uint State;public IntPtr StateData,Url;public uint Flags,Context;}
 [DllImport("wintrust.dll",ExactSpelling=true)]static extern int WinVerifyTrust(IntPtr window,ref Guid action,ref TrustData data);
 static string VerifySignature(string path,out string signer){signer="";IntPtr ptr=IntPtr.Zero;try{var file=new TrustFile{Size=(uint)Marshal.SizeOf(typeof(TrustFile)),Path=path};ptr=Marshal.AllocHGlobal(Marshal.SizeOf(typeof(TrustFile)));Marshal.StructureToPtr(file,ptr,false);var data=new TrustData{Size=(uint)Marshal.SizeOf(typeof(TrustData)),UI=2,Choice=1,File=ptr,Flags=0x1000};var action=new Guid("00AAC56B-CD44-11d0-8CC2-00C04FC295EE");int code=WinVerifyTrust(new IntPtr(-1),ref action,ref data);if(code!=0)return "未验证签名";using(var cert=new X509Certificate2(X509Certificate.CreateFromSignedFile(path))){signer=cert.GetNameInfo(X509NameType.SimpleName,false);}return "签名验证通过";}catch{return "未验证签名";}finally{if(ptr!=IntPtr.Zero){Marshal.DestroyStructure(ptr,typeof(TrustFile));Marshal.FreeHGlobal(ptr);}}}
 public static string ExecutableFromCommand(string text){if(String.IsNullOrWhiteSpace(text))return null;string value=Environment.ExpandEnvironmentVariables(text.Trim());if(value.StartsWith("\\??\\"))value=value.Substring(4);string path;if(value.StartsWith("\"")){int end=value.IndexOf('"',1);if(end<2)return null;path=value.Substring(1,end-1);}else{int end=value.IndexOf(".exe",StringComparison.OrdinalIgnoreCase);if(end<0)return null;path=value.Substring(0,end+4);}try{if(!Regex.IsMatch(path,"^[a-zA-Z]:\\\\")||!String.Equals(Path.GetExtension(path),".exe",StringComparison.OrdinalIgnoreCase))return null;return Path.GetFullPath(path);}catch{return null;}}
 public static bool Matches(ApplicationIdentity app,string[] names,string[] executables,string[] publishers){bool named=(names??new string[0]).Any(n=>app.SearchText.IndexOf(n,StringComparison.OrdinalIgnoreCase)>=0);bool exe=(executables??new string[0]).Any(n=>String.Equals(Path.GetFileName(app.Executable),n,StringComparison.OrdinalIgnoreCase));bool company=publishers==null||publishers.Length==0||publishers.Any(n=>(app.Publisher+" "+app.Company+" "+app.Signer).IndexOf(n,StringComparison.OrdinalIgnoreCase)>=0);return company&&(named||exe);}
 public static void RefreshSignature(ApplicationIdentity app){string signer;app.Signature=VerifySignature(app.Executable,out signer);app.Signer=signer;app.FingerprintCached=false;app.SignatureChecked=true;}
 internal static string InstallDirectory(string value){try{if(String.IsNullOrWhiteSpace(value))return null;string directory=Environment.ExpandEnvironmentVariables(value.Trim().Trim('"'));if(!Regex.IsMatch(directory,"^[a-zA-Z]:\\\\"))return null;return Path.GetFullPath(directory);}catch{return null;}}
 internal static bool Uninstaller(string executable,string title=null){
  string name=Path.GetFileNameWithoutExtension(executable??"");
  if(Regex.IsMatch(name,@"^(?:unins\d*|uninst|uninstall(?:er)?|unwise)(?:[-_.\s].*|\d*)$",RegexOptions.IgnoreCase))return true;
  if(String.IsNullOrWhiteSpace(title)||title.Equals("Uninstall Tool",StringComparison.OrdinalIgnoreCase)||title=="卸载工具")return false;
  return Regex.IsMatch(title.Trim(),@"^(?:uninstall\s+|卸载(?:程序|向导)?(?:\s|[：:\-]|$))",RegexOptions.IgnoreCase);
 }
 internal static string FindExecutable(string directory,Dictionary<string,string> cache,CancellationToken token,ISet<string> excluded=null){
  directory=InstallDirectory(directory);if(directory==null||ScanPolicy.Excluded(directory))return null;token.ThrowIfCancellationRequested();string found;if(cache.TryGetValue(directory,out found)&&(found==null||excluded==null||!excluded.Contains(found)))return found;
  found=null;try{var drive=new DriveInfo(Path.GetPathRoot(directory));if((drive.DriveType==DriveType.Fixed||drive.DriveType==DriveType.Removable)&&Engine.SafeAncestors(Path.Combine(directory,"probe")))foreach(string file in Directory.EnumerateFiles(directory,"*.exe",SearchOption.TopDirectoryOnly).Take(128)){token.ThrowIfCancellationRequested();if(String.Equals(Path.GetExtension(file),".exe",StringComparison.OrdinalIgnoreCase)&&!Uninstaller(file)&&(excluded==null||!excluded.Contains(file))){found=file;break;}}}catch(OperationCanceledException){throw;}catch{}cache[directory]=found;return found;
 }
 static bool LocalExecutable(string path,Dictionary<string,bool> volumes){try{string root=Path.GetPathRoot(path);bool local;if(!volumes.TryGetValue(root,out local)){var drive=new DriveInfo(root);local=drive.DriveType==DriveType.Fixed||drive.DriveType==DriveType.Removable;volumes[root]=local;}return local;}catch{return false;}}
 public static DiscoveryResult Scan(IEnumerable<string> portable,CancellationToken token,Action<string> status,ScanSession session=null){
  var result=new DiscoveryResult();var items=new Dictionary<string,ApplicationIdentity>(StringComparer.OrdinalIgnoreCase);var metadata=new Dictionary<string,ApplicationIdentity>(StringComparer.OrdinalIgnoreCase);var directories=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);var volumes=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);var uninstallers=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var launchers=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  Action<string,string,string,string,string> add=(name,publisher,directory,exe,evidence)=>{token.ThrowIfCancellationRequested();exe=ExecutableFromCommand(exe);if(Uninstaller(exe,evidence=="卸载注册信息"?null:name)||exe!=null&&uninstallers.Contains(exe)){if(evidence!="卸载注册信息")return;exe=FindExecutable(directory,directories,token,uninstallers);}if(String.IsNullOrWhiteSpace(name)&&exe==null)return;try{if(!String.IsNullOrEmpty(directory)){directory=Environment.ExpandEnvironmentVariables(directory.Trim().Trim('"'));if(!Path.IsPathRooted(directory)||directory.StartsWith("\\\\"))directory=null;else directory=Path.GetFullPath(directory);}}catch{directory=null;}string key=exe??((directory??"")+"|"+name);ApplicationIdentity app;if(items.TryGetValue(key,out app)){if(app.Evidence.IndexOf(evidence,StringComparison.Ordinal)<0)app.Evidence+="、"+evidence;return;}app=new ApplicationIdentity{Name=name??Path.GetFileNameWithoutExtension(exe),Publisher=publisher??"",InstallDirectory=directory??(exe==null?"":Path.GetDirectoryName(exe)),Executable=exe??"",Evidence=evidence,Signature="无可核验程序",Version="",Product="",Company="",Signer=""};
   if(exe!=null&&LocalExecutable(exe,volumes)&&!ScanPolicy.Excluded(exe)&&File.Exists(exe)&&Engine.SafeAncestors(exe)){ApplicationIdentity info;if(!metadata.TryGetValue(exe,out info)){Func<ApplicationIdentity> read=()=>{var fresh=new ApplicationIdentity{Signature="签名按需验证",Signer="",Product="",Company="",Version="",Name=""};try{var v=FileVersionInfo.GetVersionInfo(exe);fresh.Name=v.FileDescription??"";fresh.Product=v.ProductName??"";fresh.Company=v.CompanyName??"";fresh.Version=v.ProductVersion??"";}catch{}return fresh;};info=session==null?read():session.Fingerprint(exe,read);metadata[exe]=info;}app.Product=info.Product;app.Company=info.Company;app.Version=info.Version;app.Signature=info.Signature;app.Signer=info.Signer;app.FingerprintCached=info.FingerprintCached;if(String.IsNullOrWhiteSpace(app.Name))app.Name=info.Product;if(app.Name.StartsWith("@",StringComparison.Ordinal))app.Name=!String.IsNullOrWhiteSpace(info.Name)?info.Name:!String.IsNullOrWhiteSpace(info.Product)?info.Product:Path.GetFileNameWithoutExtension(exe);}
   items[key]=app;
  };
  if(status!=null)status("读取卸载项与 App Paths…");var views=Environment.Is64BitOperatingSystem?new[]{RegistryView.Registry64,RegistryView.Registry32}:new[]{RegistryView.Registry32};
  foreach(string path in new[]{RegistryCleaner.Uninstall,RegistryCleaner.AppPaths})foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in views)try{using(var root=RegistryKey.OpenBaseKey(hive,view))using(var parent=root.OpenSubKey(path,false)){if(parent==null)continue;foreach(string name in parent.GetSubKeyNames().Take(4096)){token.ThrowIfCancellationRequested();try{using(var key=parent.OpenSubKey(name,false)){if(key==null)continue;if(path==RegistryCleaner.AppPaths)add(name,"",null,key.GetValue("")as string,"App Paths");else{string title=key.GetValue("DisplayName")as string;if(String.IsNullOrWhiteSpace(title))continue;string location=key.GetValue("InstallLocation")as string,exe=ExecutableFromCommand(key.GetValue("DisplayIcon")as string);if(exe!=null&&!Uninstaller(exe)){launchers.Add(exe);uninstallers.Remove(exe);}foreach(string value in new[]{key.GetValue("UninstallString")as string,key.GetValue("QuietUninstallString")as string}){string uninstaller=ExecutableFromCommand(value);if(uninstaller!=null&&!launchers.Contains(uninstaller)&&!ScanPolicy.Excluded(uninstaller)&&(Uninstaller(uninstaller)||exe!=null&&!String.Equals(exe,uninstaller,StringComparison.OrdinalIgnoreCase)))uninstallers.Add(uninstaller);}if(exe==null||Uninstaller(exe)||uninstallers.Contains(exe))exe=FindExecutable(location,directories,token,uninstallers);add(title,key.GetValue("Publisher")as string,location,exe,"卸载注册信息");}}}catch{result.Unreadable++;}}}}catch(OperationCanceledException){throw;}catch{result.Unreadable++;}
  if(status!=null)status("检查进程与服务…");try{foreach(var p in Process.GetProcesses()){using(p){token.ThrowIfCancellationRequested();try{add(p.ProcessName,"",null,p.MainModule.FileName,"运行进程");}catch{}}}}catch(OperationCanceledException){throw;}catch{result.Unreadable++;}
  try{using(var root=RegistryKey.OpenBaseKey(RegistryHive.LocalMachine,RegistryView.Default))using(var services=root.OpenSubKey(@"SYSTEM\CurrentControlSet\Services",false)){if(services!=null)foreach(string name in services.GetSubKeyNames().Take(4096)){token.ThrowIfCancellationRequested();try{using(var key=services.OpenSubKey(name,false)){if(key==null)continue;string exe=ExecutableFromCommand(key.GetValue("ImagePath")as string);if(exe!=null)add(key.GetValue("DisplayName")as string??name,"",null,exe,"服务注册信息");}}catch{}}}}catch(OperationCanceledException){throw;}catch{result.Unreadable++;}
  if(status!=null)status("读取开始菜单快捷方式…");foreach(string menu in new[]{Environment.GetFolderPath(Environment.SpecialFolder.StartMenu),Environment.GetFolderPath(Environment.SpecialFolder.CommonStartMenu)})foreach(string link in FilesBounded(menu,".lnk",5,2000,token)){object shell=null,shortcut=null;try{var type=Type.GetTypeFromProgID("WScript.Shell");shell=Activator.CreateInstance(type);shortcut=type.InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{link});string target=shortcut.GetType().InvokeMember("TargetPath",System.Reflection.BindingFlags.GetProperty,null,shortcut,null)as string;if(ExecutableFromCommand(target)!=null)add(Path.GetFileNameWithoutExtension(link),"",null,target,"开始菜单");}catch{}finally{if(shortcut!=null&&Marshal.IsComObject(shortcut))Marshal.FinalReleaseComObject(shortcut);if(shell!=null&&Marshal.IsComObject(shell))Marshal.FinalReleaseComObject(shell);}}
  if(status!=null)status("检查指定便携目录…");foreach(string root in portable??new string[0])foreach(string exe in FilesBounded(root,".exe",3,400,token)){add(Path.GetFileNameWithoutExtension(exe),"",Path.GetDirectoryName(exe),exe,"自选便携目录");ApplicationIdentity found;if(items.TryGetValue(exe,out found))found.PortableRoot=root;}result.Applications=items.Values.Where(a=>!Uninstaller(a.Executable)&&!uninstallers.Contains(a.Executable)).OrderBy(a=>a.Name,StringComparer.CurrentCultureIgnoreCase).ToList();return result;
 }
 public static IEnumerable<string> FilesBounded(string root,string extension,int depth,int max,CancellationToken token){if(String.IsNullOrEmpty(root)||ScanPolicy.Excluded(root)||!Directory.Exists(root))yield break;var queue=new Queue<Tuple<string,int>>();queue.Enqueue(Tuple.Create(root,0));int examined=0,files=0;while(queue.Count>0&&examined++<5000&&files<max){token.ThrowIfCancellationRequested();var item=queue.Dequeue();FileSystemInfo[] entries;try{if(ScanPolicy.Excluded(item.Item1)||!Engine.SafeAncestors(Path.Combine(item.Item1,"probe")))continue;entries=new DirectoryInfo(item.Item1).GetFileSystemInfos();}catch{continue;}foreach(var e in entries){token.ThrowIfCancellationRequested();if(ScanPolicy.Excluded(e.FullName)||(e.Attributes&FileAttributes.ReparsePoint)!=0)continue;if((e.Attributes&FileAttributes.Directory)!=0){if(item.Item2<depth)queue.Enqueue(Tuple.Create(e.FullName,item.Item2+1));}else if(String.Equals(e.Extension,extension,StringComparison.OrdinalIgnoreCase)){yield return e.FullName;if(++files>=max)yield break;}}}}
}
